static const char* vertex_shader_source = R"(
#version 330 core

layout (location = 0) in vec3 vertex_position;
layout (location = 1) in vec3 vertex_colour_a;
layout (location = 2) in vec3 vertex_colour_b;
layout (location = 3) in vec2 vertex_uv;

uniform mat4 world_to_clip;

varying vec3 colour_a;
varying vec3 colour_b;
varying vec2 uv;

void main()
{
    colour_a = vertex_colour_a;
    colour_b = vertex_colour_b;
    uv = vertex_uv;
    gl_Position = world_to_clip * vec4(vertex_position, 1.0f);
}
)";

static const char* fragment_shader_source = R"(
#version 330 core

out vec4 FragColor;

uniform sampler2D font_atlas;

varying vec3 colour_a;
varying vec3 colour_b;
varying vec2 uv;

void main()
{
    if (texture(font_atlas, uv).r > 0.5f)
        FragColor = vec4(colour_a, 1.0f);
    else
        FragColor = vec4(colour_b, 1.0f);
}
)";

